/*
 * A125219  a(n) is the smallest positive integer not occurring earlier in the
 *          sequence such that sum{k=1 to n} a(k) = j^r, j = any positive
 *          integer, r = any integer >= 2.
 * https://oeis.org/A125219
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 12, u16 n <= 68, u32 n <= 68, u64 n <= 68, u128 n <= 68,
 *            big any n
 * Helpers:   bitlen_seq_t, pow2, seq_pow
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A125219: generated by greedy construction
 *   a(1) = 1
 *   for n > 1: a(n) is the smallest positive integer not used earlier
 *   such that sum_{k=1}^{n} a(k) is a perfect power j^r (r ≥ 2).
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include "../utils/seq_pow.h"      /* seq_pow(seq_t base, idx_t exp)      */
#include "../utils/pow2.h"        /* pow2(idx_t exp)                     */
#include "../utils/bitlen_seq_t.h"/* bitlen_seq_t(seq_t x)              */

static seq_t* seq_cache = NULL;          /* cached terms                     */
static size_t seq_len  = 0;              /* number of cached terms            */
static size_t seq_cap  = 0;              /* capacity of seq_cache             */
static seq_t   sum     = 0;              /* current prefix sum                */
static bool*   used    = NULL;           /* used numbers flag                 */
static size_t used_cap = 0;              /* size of used array                */

/* enlarge a bool array to accommodate index >= new_cap */
static void grow_used(size_t new_cap)
{
    if (new_cap <= used_cap) return;
    bool* new_used = (bool*)realloc(used, new_cap * sizeof(bool));
    if (!new_used) exit(EXIT_FAILURE);
    for (size_t i = used_cap; i < new_cap; ++i) new_used[i] = false;
    used = new_used;
    used_cap = new_cap;
}

/* enlarge the sequence cache to at least new_cap terms */
static void grow_seq(size_t new_cap)
{
    if (new_cap <= seq_cap) return;
    seq_t* new_seq = (seq_t*)realloc(seq_cache, new_cap * sizeof(seq_t));
    if (!new_seq) exit(EXIT_FAILURE);
    seq_cache = new_seq;
    seq_cap   = new_cap;
}

/* test whether x is a perfect power j^r (r ≥ 2, j ≥ 1) */
static bool is_perfect_power(seq_t x)
{
    if (x == (seq_t)1) return true;                 /* 1 = 1^r for any r */
    if (x < (seq_t)2) return false;

    unsigned bits = bitlen_seq_t(x);                /* bit length of x */
    /* try exponents r = 2 .. bits-1 */
    for (int r = 2; r < (int)bits; ++r) {
        /* compute upper bound for j as 2^ceil(bits/r) */
        seq_t low  = (seq_t)1;
        seq_t high = pow2(((bits + r - 1) / r));     /* safe upper bound */

        /* binary search for integer j */
        while (low <= high) {
            seq_t mid = (low + high) / (seq_t)2;
            seq_t mid_pow = seq_pow(mid, (idx_t)r);
            if (mid_pow == x) return true;
            if (mid_pow < x) {
                low = mid + (seq_t)1;
            } else {
                high = mid - (seq_t)1;
            }
        }
    }
    return false;
}

/* compute the nth term of the sequence */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;                    /* undefined for 0 */

    /* extend the cache if necessary */
    while (seq_len < (size_t)n) {
        /* find the next term */
        seq_t   candidate = (seq_t)1;
        seq_t   next_sum;
        while (true) {
            grow_used((size_t)candidate + 1);
            if (!used[(size_t)candidate]) {
                next_sum = sum + candidate;
                if (is_perfect_power(next_sum)) break;
            }
            ++candidate;
        }

        /* store the new term */
        if (seq_len == seq_cap) grow_seq(seq_cap ? seq_cap * 2 : 128);
        seq_cache[seq_len] = candidate;
        seq_len++;

        used[(size_t)candidate] = true;
        sum = next_sum;
    }

    return seq_cache[n - 1];
}
